"""Apply the model JSON protocol compatibility fix to the existing project.
Put this file beside README.md and run with your project Python.
Source changes are guarded by hashes; originals are backed up under examples/.
No credentials, virtual environment, Git history or existing live traces are changed.
"""
import argparse
import base64
import hashlib
import json
from pathlib import Path
from datetime import datetime, timezone
import zlib

PAYLOAD = ''


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--project-dir',default=str(Path(__file__).resolve().parent))
    args=parser.parse_args()
    root=Path(args.project_dir).resolve()
    if not (root/'src/enterprise_qa/agent.py').is_file() or not (root/'README.md').is_file():
        print('Place this installer in the project root beside README.md, then rerun.')
        return 2
    package=json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))
    changes=[]
    # Validate every source replacement before writing any file.
    for name, content in package['files'].items():
        target=(root/name).resolve()
        if root not in target.parents:
            print('Invalid update path; stopped.');return 2
        current=target.read_bytes() if target.exists() else None
        new=content.encode('utf-8')
        if current is not None and current.replace(b'\r\n',b'\n')==new:
            continue
        # Report/docs are additive; preserve existing customized copies.
        if name.startswith(('docs/','examples/')) and current is not None:
            print('Preserving existing file: '+name);continue
        actual=hashlib.sha256(current.replace(b'\r\n',b'\n')).hexdigest() if current is not None else None
        if actual not in package['old_hashes'][name]:
            print('Existing file differs from the expected version: '+name)
            print('No changes made. Keep this output for review; local source edits were preserved.')
            return 1
        changes.append((name,target,current,new))
    stamp=datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')
    backup=root/'examples/protocol-fix-backups'/stamp
    for name,target,current,new in changes:
        if current is not None:
            saved=backup/name;saved.parent.mkdir(parents=True,exist_ok=True);saved.write_bytes(current)
        target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(new)
        print('Updated: '+name)
    # Only revise known test counts; keep personal prose and other local edits.
    for name in ('README.md','docs/03-evaluation.md','docs/04-ai-usage.md','docs/06-submission.md'):
        target=root/name
        if not target.exists():continue
        original=target.read_bytes()
        text=original.decode('utf-8-sig')
        changed=text.replace('34 项','53 项').replace('34 个','53 个').replace('40 项','53 项').replace('40 个','53 个')
        if name=='docs/03-evaluation.md' and '10-model-protocol-fix.md' not in changed:
            changed+='\n\n## 真实失败反馈与修复\n\n用户机器曾出现提前澄清和检索后协议解析失败。修复、限制和复测要求见 [模型协议修复记录](10-model-protocol-fix.md) 与 [提前澄清记录](09-early-clarification-fix.md)。53 项自动测试通过不代表真实模型修复已通过，需重新运行。\n'
        if changed!=text:
            saved=backup/name;saved.parent.mkdir(parents=True,exist_ok=True);saved.write_bytes(original)
            target.write_text(changed,encoding='utf-8')
    print('Update complete. Existing .env, .venv, Git history and live traces were preserved.')
    print('Run: .\\.venv\\Scripts\\python.exe scripts/test.py')
    print('Then save a NEW normal live run; keep the previous failure trace unchanged.')
    return 0

if __name__=='__main__':
    raise SystemExit(main())
